import Foundation

struct AZGroupedSection {
    let sectionTitle: String
    let items: [AZOrderedListItem]
}

enum AZOrderedListSorter {
    private static var pinyinCache: [Character: String] = [:]
    private static let maxCacheSize = 1000
    private static let cjkUnifiedIdeographRangeStart: UInt32 = 0x4E00
    private static let cjkUnifiedIdeographRangeEnd: UInt32 = 0x9FFF
    private static let pinyinFirstLetters: [Character] = Array(
        "")

    static func group(_ items: [AZOrderedListItem]) -> (sections: [AZGroupedSection], titles: [String]) {
        let sortedItems = items.sorted { item1, item2 in
            let title1 = item1.title ?? item1.id
            let title2 = item2.title ?? item2.id
            return title1.localizedCaseInsensitiveCompare(title2) == .orderedAscending
        }
        var groupedDict: [String: [AZOrderedListItem]] = [:]
        for item in sortedItems {
            let title = item.title ?? item.id
            let firstChar = getFirstCharacter(title)
            let sectionTitle = getSectionTitle(firstChar)
            groupedDict[sectionTitle, default: []].append(item)
        }
        let sortedSections = groupedDict.keys.sorted { sortSections($0, $1) }
        let sections = sortedSections.map { title in
            AZGroupedSection(sectionTitle: title, items: groupedDict[title] ?? [])
        }
        return (sections, sortedSections)
    }

    private static func getFirstCharacter(_ text: String) -> String {
        guard let firstChar = text.first else { return "#" }
        let unicodeValue = firstChar.unicodeScalars.first?.value ?? 0
        if unicodeValue >= cjkUnifiedIdeographRangeStart && unicodeValue <= cjkUnifiedIdeographRangeEnd {
            return getChinesePinyinFirstLetter(String(firstChar))
        }
        if (firstChar >= "A" && firstChar <= "Z") || (firstChar >= "a" && firstChar <= "z") {
            return String(firstChar).uppercased()
        }
        return "#"
    }

    private static func getSectionTitle(_ firstChar: String) -> String {
        if firstChar.rangeOfCharacter(from: .letters) != nil {
            return firstChar.uppercased()
        }
        return "#"
    }

    private static func sortSections(_ section1: String, _ section2: String) -> Bool {
        if section1 == "#" && section2 != "#" {
            return false
        } else if section1 != "#" && section2 == "#" {
            return true
        } else {
            return section1 < section2
        }
    }

    private static func getChinesePinyinFirstLetter(_ chinese: String) -> String {
        guard let firstChar = chinese.first else { return "#" }
        if let cached = pinyinCache[firstChar] {
            return cached
        }
        let hanziStart: UInt32 = 19968
        let hanziCount = pinyinFirstLetters.count
        let unicodeValue = firstChar.unicodeScalars.first?.value ?? 0
        if unicodeValue >= hanziStart && unicodeValue < hanziStart + UInt32(hanziCount) {
            let index = Int(unicodeValue - hanziStart)
            if index >= 0 && index < hanziCount {
                let result = String(pinyinFirstLetters[index]).uppercased()
                addToPinyinCache(firstChar, result)
                return result
            }
        }
        let result = "#"
        addToPinyinCache(firstChar, result)
        return result
    }

    private static func addToPinyinCache(_ char: Character, _ pinyin: String) {
        if pinyinCache.count >= maxCacheSize {
            let keysToRemove = Array(pinyinCache.keys.prefix(maxCacheSize / 2))
            for key in keysToRemove {
                pinyinCache.removeValue(forKey: key)
            }
        }
        pinyinCache[char] = pinyin
    }
}
